import {
    FileQuestion
} from 'lucide-react';

import { DynamicForm } from '@/Components/Core/DynamicCrud/DynamicForm';
import StatusBadge from '@/Components/UI/StatusBadge';
import { useTranslations } from '@/Hooks/useTranslations';
import type { CrudConfig, CrudPageProps } from '@/Types/crud';
import { limitText } from '@/Utils/helpers';
import z from 'zod';

export function useFaqConfig(props: CrudPageProps): CrudConfig {

    const { t } = useTranslations();

    const modelProperty = props?.modelProperty;
    const advanceFilterOptions = props?.advanceFilterOptions || [];
    const routePrefix = modelProperty?.routePrefix;


    const baseBreadcrumbs = [
        { label: t('Dashboard'), href: route('backend.dashboard') },
        { label: t('FAQS'), href: route(`${routePrefix}.index`) },
    ];

    return {

        formComponent: DynamicForm,
        fetchToggle: false,
        form: {
            title: {
                create: t('Create FAQ'),
                edit: t('Edit FAQ'),
            },
            description: {
                create: t('Add a new faq to the system'),
                edit: t('Update FAQ information'),
            },
            submitButtonText: {
                create: t('Create FAQ'),
                edit: t('Update FAQ'),
            },

            fields: [
                {
                    name: 'question',
                    label: t('Question'),
                    type: 'text',
                    placeholder: t('Enter question'),
                    required: true,
                    section: 'basic',
                    gridColumn: 'span 3'
                },
                {
                    name: 'answer',
                    label: t('Answer'),
                    type: 'textarea',
                    placeholder: t('Enter answer'),
                    required: true,
                    section: 'basic',
                    gridColumn: 'span 3',
                    description: t('Answer to the question'),

                },


                {
                    name: 'status',
                    label: t('Status'),
                    type: 'select',
                    required: true,
                    options: [
                        { value: 'active', label: 'Active' },
                        { value: 'inactive', label: 'Inactive' },
                    ],
                    section: 'basic',
                },


            ],
        },

        formValidationRules: {

            question: z.string().min(1, 'Question is required').max(191),
            answer: z.string().min(1, 'Answer is required').max(191),
            status: z.string().min(1, 'Status is required').max(191),


        },

        resource: 'FAQ',
        resourcePlural: 'FAQs',
        title: t('FAQs'),
        description: t('Manage FAQ accounts and permissions'),

        routes: {
            index: `${routePrefix}.index`,
            create: `${routePrefix}.create`,
            edit: `${routePrefix}.edit`,
            store: `${routePrefix}.store`,
            update: `${routePrefix}.update`,
            destroy: `${routePrefix}.destroy`,
        },

        formDisplayMode: 'modal',
        viewDisplayMode: 'modal',
        statusType: 'binary',

        breadcrumbs: {
            index: [
                { label: t('Dashboard'), href: route('backend.dashboard') },
                { label: t('FAQs'), href: null, active: true },
            ],
            create: [
                ...baseBreadcrumbs,
                { label: t('Create'), href: null, active: true },
            ],
            update: [
                ...baseBreadcrumbs,
                { label: t('Update'), href: null, active: true },
            ],
        },

        table: {
            selectable: false,
            searchable: true,
            serializable: true,
            searchPlaceholder: t('Search FAQs by question, answer...'),
            sortable: true,
            defaultSort: 'created_at',
            defaultSortDirection: 'desc',
            emptyMessage: t('No FAQs available. Create your first FAQ to get started.'),
            emptyMessageIcon: FileQuestion,

            columns: [
                {
                    key: 'question',
                    label: t('Question'),
                    sortable: false,
                    filterable: true,
                    priority: 0,
                    render: (row: any) => (
                        <div className="text-sm text-gray-900 dark:text-gray-100">{limitText(row.question, 20)}</div>
                    )

                },
                {
                    key: 'answer',
                    label: t('Answer'),
                    sortable: false,
                    priority: 2,
                    render: (row: any) => (
                        <div className="text-sm text-gray-900 dark:text-gray-100">{limitText(row.answer, 20)}</div>
                    )
                },

                {
                    key: 'status',
                    label: 'Status',
                    sortable: false,
                    filterable: false,
                    priority: 3,
                    render: (row: any) => {

                        return (
                            <>
                                <div className='mt-1.5'>
                                    <StatusBadge status={row.status} />
                                </div>
                            </>
                        );
                    },
                },

                {
                    key: 'created_at',
                    label: t('Created at'),
                    sortable: false,
                    priority: 4,
                    renderType: 'date',
                },
            ],

        },


        filters: {
            searchFields: ['question', 'answer'],
            filterFields: advanceFilterOptions,
        },

        permissions: {
            actions: {
                create: 'faq.create',
                edit: 'faq.edit',
                view: 'faq.view',
                delete: 'faq.delete',
            },
        },

        actionConstraints: {
            delete: [
                {
                    field: 'is_owner',
                    checkValue: true,
                    message: 'Cannot delete owner account',
                },
                {
                    field: 'orders_count',
                    message: 'Cannot delete FAQ with existing orders',
                },
            ],
            bulkDelete: [
                {
                    field: 'is_owner',
                    checkValue: true,
                    message: 'Cannot delete owner account',
                },
            ],
        },

        destroyDialogConfig: {

            title: t(`Delete FAQ`),
            description: t(`Are you sure you want to delete this FAQ? This action cannot be undone.`),

        },

        labels: {
            singular: 'FAQ',
            plural: 'FAQs',
            key: 'FAQ',
        },

        saveAlertInfo: {
            title: t('FAQ Account Configuration'),
            description: t('Fill in the details below to save the FAQ account. All fields marked as required must be completed.'),
        }
    }
};

